import { useCallback, useMemo } from 'react';
import { getDoorGatedNeighbor, findDoorsTouchingCell } from './dungeon-door-rules.js';

export function useMapInteraction({ gameSession, foundPassages = [], sessionManager }) {

    const isFrontOfDoor = useCallback((x, y) => {
        if (!gameSession?.currentMap?.grid) return null;

        const activeHero = gameSession.heroes?.find(h => h.turnOrder === gameSession.currentTurn);
        if (!activeHero) return null;
        const hx = activeHero.x;
        const hy = activeHero.y;

        /**
         * Sceglie destinazione e passaggio quando l'eroe è in `(hx, hy)` ed è
         * coinvolto nella geometria di una porta/passaggio.
         *
         * Geometria DIREZIONALE (lato +1):
         *   - door cell:           (px, py)
         *   - vicino gestito (+1): (px, py+1) per oriz=true,
         *                          (px+1, py) per oriz=false.
         *
         * - Se l'eroe sta sulla door cell → destinazione = vicino +1
         *   (purché esista in grid e non sia muro/blocco magico).
         * - Se l'eroe sta sul vicino +1 → destinazione = door cell
         *   (classica "apri porta da una stanza").
         */
        const pickFrontOfPassage = (passage) => {
            const px = Number(passage.x);
            const py = Number(passage.y);
            const neighbor = getDoorGatedNeighbor(passage);
            if (!neighbor) return null;

            const isOpenable = (cell) =>
                cell != null && !cell.arnt?.antroc && !cell.arnt?.inv;

            const heroIsOnPassageCell = hx === px && hy === py;
            const heroIsNeighbor = hx === neighbor.x && hy === neighbor.y;

            let dest = null;
            if (heroIsOnPassageCell) {
                const cell = gameSession.currentMap.grid.find(c => c.x === neighbor.x && c.y === neighbor.y);
                if (!isOpenable(cell)) return null;
                dest = neighbor;
            } else if (heroIsNeighbor) {
                const passageCell = gameSession.currentMap.grid.find(c => c.x === px && c.y === py);
                if (!isOpenable(passageCell)) return null;
                dest = { x: px, y: py };
            } else {
                return null;
            }
            return { found: true, destination: dest, passageCell: { x: px, y: py } };
        };

        // === 1. Porte (geometria direzionale +1) ===
        const heroDoors = findDoorsTouchingCell(gameSession.currentMap.porte, hx, hy);
        for (const door of heroDoors) {
            const doorKey = `${door.x},${door.y}`;
            if (gameSession.openedDoors?.includes(doorKey)) continue;
            const result = pickFrontOfPassage(door);
            if (result) return result;
        }

        // === 2. Passaggi segreti scoperti (stessa geometria delle porte) ===
        if (foundPassages?.length) {
            const heroPassages = findDoorsTouchingCell(foundPassages, hx, hy);
            for (const passage of heroPassages) {
                const result = pickFrontOfPassage(passage);
                if (result) return result;
            }
        }
        return null;
    }, [gameSession, foundPassages]);

    const openPassage = useCallback((passageX, passageY, destinationX, destinationY) => {
        if (!gameSession?.currentMap) return false;

        const isDoor = gameSession.currentMap.porte?.some(p => p.x === passageX && p.y === passageY);
        const isSecret = foundPassages?.some(p => p.x === passageX && p.y === passageY);

        if (!isDoor && !isSecret) return false;

        return sessionManager?.openPassage(passageX, passageY, destinationX, destinationY, foundPassages) ?? false;
    }, [gameSession, foundPassages, sessionManager]);

    // Memoizzazione del wrapper: senza questa, ogni render produce un literal
    // `{ isFrontOfDoor, openPassage }` con identità nuova. I consumer che lo
    // tengono come `useEffect` dependency (es. il watchdog di
    // `useTurnLogic` che ricalcola `canOpenDoor`) entrerebbero in loop:
    // cambia ref → effect fires → setState → re-render → nuovo literal → ...
    // Memoizzando sull'identità delle callback (stabili grazie a useCallback)
    // l'oggetto resta lo stesso finché non cambiano davvero gameSession,
    // foundPassages o sessionManager.
    return useMemo(
        () => ({ isFrontOfDoor, openPassage }),
        [isFrontOfDoor, openPassage]
    );
}
